('6ba05968-ea1f-5088-a5e8-9ea0719511b1', 'iq-L5-G01', 5, 'LOGIC'::"IqItemKind", ARRAY['L5C']::text[], '{"uz":"“Imtihondan o‘tgan har kim sertifikat oladi” — to‘g‘ri. Nodira sertifikat olmadi. Demak:","ru":"«Каждый, кто сдал экзамен, получает сертификат» — верно. Нодира не получила сертификат. Значит:","en":"“Everyone who passes the exam gets a certificate” is true. Nodira did not get a certificate. So:"}'::jsonb, '[{"key":"A","text":{"uz":"Bilib bo‘lmaydi","ru":"Нельзя определить","en":"Cannot be determined"}},{"key":"B","text":{"uz":"Nodira imtihondan o‘tgan","ru":"Нодира сдала экзамен","en":"Nodira passed the exam"}},{"key":"C","text":{"uz":"Nodira imtihondan o‘tmagan","ru":"Нодира не сдала экзамен","en":"Nodira did not pass the exam"}},{"key":"D","text":{"uz":"sertifikat faqat imtihon uchun beriladi","ru":"сертификат дают только за экзамен","en":"certificates are given only for the exam"}}]'::jsonb, 'C', 0.3, 'contrapositive', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('6c62f05c-135f-5cc8-80cd-30fb46606fd6', 'iq-L5-G02', 5, 'LOGIC'::"IqItemKind", ARRAY['L5D']::text[], '{"uz":"Aziz, Bobur va Doniyor — shifokor, muhandis va o‘qituvchi. Aziz shifokor emas. Bobur shifokor ham, muhandis ham emas. Doniyor kim?","ru":"Азиз, Бобур и Дониёр — врач, инженер и учитель. Азиз не врач. Бобур не врач и не инженер. Кто Дониёр?","en":"Aziz, Bobur and Doniyor are a doctor, an engineer and a teacher. Aziz is not the doctor. Bobur is neither the doctor nor the engineer. Who is Doniyor?"}'::jsonb, '[{"key":"A","text":{"uz":"Bilib bo‘lmaydi","ru":"Нельзя определить","en":"Cannot be determined"}},{"key":"B","text":{"uz":"o‘qituvchi","ru":"учитель","en":"the teacher"}},{"key":"C","text":{"uz":"shifokor","ru":"врач","en":"the doctor"}},{"key":"D","text":{"uz":"muhandis","ru":"инженер","en":"the engineer"}}]'::jsonb, 'C', 0.46, 'assignment', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('ec029327-da21-58ef-876b-8398b56468d5', 'iq-L5-G03', 5, 'LOGIC'::"IqItemKind", ARRAY['L5D']::text[], '{"uz":"Qaysi gap “Hamma talabalar kitob o‘qiydi” degan gapni inkor qiladi?","ru":"Какое утверждение опровергает фразу «Все студенты читают книги»?","en":"Which statement contradicts “All students read books”?"}'::jsonb, '[{"key":"A","text":{"uz":"Hech bir talaba kitob o‘qimaydi","ru":"Ни один студент не читает книг","en":"No student reads books"}},{"key":"B","text":{"uz":"Kamida bitta talaba kitob o‘qimaydi","ru":"Хотя бы один студент не читает книг","en":"At least one student does not read books"}},{"key":"C","text":{"uz":"Ba’zi talabalar kitob o‘qiydi","ru":"Некоторые студенты читают книги","en":"Some students read books"}},{"key":"D","text":{"uz":"Talabalar faqat kitob o‘qiydi","ru":"Студенты читают только книги","en":"Students read only books"}}]'::jsonb, 'B', 0.59, 'negation', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('7ba2c226-382e-57ef-b674-05812c9e2027', 'iq-L5-G04', 5, 'LOGIC'::"IqItemKind", '{}'::text[], '{"uz":"Narx avval 20% oshdi, keyin 20% kamaydi. Yakuniy narx boshlang‘ich narxga nisbatan qanday?","ru":"Цену сначала повысили на 20%, потом снизили на 20%. Какой стала итоговая цена по сравнению с начальной?","en":"A price rose by 20% and then fell by 20%. How does the final price compare with the original?"}'::jsonb, '[{"key":"A","text":{"uz":"o‘zgarmagan","ru":"не изменилась","en":"the same"}},{"key":"B","text":{"uz":"4% arzonroq","ru":"на 4% ниже","en":"4% lower"}},{"key":"C","text":{"uz":"2% arzonroq","ru":"на 2% ниже","en":"2% lower"}},{"key":"D","text":{"uz":"4% qimmatroq","ru":"на 4% выше","en":"4% higher"}}]'::jsonb, 'B', 0.69, 'percent', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('692048eb-d662-50c8-bc5c-01d89ba74e3a', 'iq-L5-G05', 5, 'LOGIC'::"IqItemKind", ARRAY['L5C']::text[], '{"uz":"“Imtihondan o‘tgan har kim sertifikat oladi” — to‘g‘ri. Bekzod sertifikat oldi. Demak:","ru":"«Каждый, кто сдал экзамен, получает сертификат» — верно. Бекзод получил сертификат. Значит:","en":"“Everyone who passes the exam gets a certificate” is true. Bekzod got a certificate. So:"}'::jsonb, '[{"key":"A","text":{"uz":"Bekzod albatta imtihondan o‘tgan","ru":"Бекзод обязательно сдал экзамен","en":"Bekzod certainly passed the exam"}},{"key":"B","text":{"uz":"Bekzod imtihondan o‘tmagan","ru":"Бекзод не сдал экзамен","en":"Bekzod did not pass the exam"}},{"key":"C","text":{"uz":"sertifikat faqat imtihon uchun beriladi","ru":"сертификат дают только за экзамен","en":"certificates are given only for the exam"}},{"key":"D","text":{"uz":"bilib bo‘lmaydi: sertifikat boshqa sabab bilan ham berilgan bo‘lishi mumkin","ru":"нельзя определить: сертификат могли дать и по другой причине","en":"cannot be determined: it may have been given for another reason"}}]'::jsonb, 'D', 0.97, 'fallacy', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('5620f806-35ec-5c78-9c62-9f75a6308787', 'iq-L5-G06', 5, 'LOGIC'::"IqItemKind", ARRAY['L5C']::text[], '{"uz":"Orolda rostgo‘ylar faqat rost, yolg‘onchilar faqat yolg‘on gapiradi. Kimdir “Men yolg‘onchiman” dedi. Nima deyish mumkin?","ru":"На острове правдивые всегда говорят правду, а лжецы всегда лгут. Кто-то сказал: «Я лжец». Что можно утверждать?","en":"On an island, truth-tellers always tell the truth and liars always lie. Someone says, “I am a liar.” What can you conclude?"}'::jsonb, '[{"key":"A","text":{"uz":"u ham rostgo‘y, ham yolg‘onchi","ru":"он и правдивый, и лжец","en":"the speaker is both"}},{"key":"B","text":{"uz":"u rostgo‘y","ru":"он правдивый","en":"the speaker is a truth-teller"}},{"key":"C","text":{"uz":"orol aholisidan hech kim bunday deya olmaydi","ru":"ни один житель острова не мог так сказать","en":"no islander could have said this"}},{"key":"D","text":{"uz":"u yolg‘onchi","ru":"он лжец","en":"the speaker is a liar"}}]'::jsonb, 'C', 0.95, 'paradox', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('fe002976-c3e1-57f0-b8f8-2944ba79900b', 'iq-L5-G07', 5, 'LOGIC'::"IqItemKind", ARRAY['L5D']::text[], '{"uz":"Sinfdagi 30 o‘quvchidan 18 tasi ingliz, 15 tasi rus tilini o‘rganadi, 5 tasi hech birini o‘rganmaydi. Nechtasi ikkala tilni o‘rganadi?","ru":"Из 30 учеников 18 изучают английский, 15 — русский, а 5 не изучают ни один из них. Сколько учеников изучают оба языка?","en":"In a class of 30, 18 study English, 15 study Russian, and 5 study neither. How many study both?"}'::jsonb, '[{"key":"A","text":{"uz":"3","ru":"3","en":"3"}},{"key":"B","text":{"uz":"10","ru":"10","en":"10"}},{"key":"C","text":{"uz":"13","ru":"13","en":"13"}},{"key":"D","text":{"uz":"8","ru":"8","en":"8"}}]'::jsonb, 'D', 1.33, 'sets', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
